-- Lección 1.1: Números primos y compuestos
INSERT INTO Lecciones (Leccion_Nombre, Leccion_Contenido, Leccion_Orden, Tema_Id) VALUES ('Números primos y compuestos', 'Un número es **divisor** de otro cuando al dividir el residuo es cero. Contar los divisores de un número nos dice qué tipo de número es.\n\n| Número | Divisores | Cantidad |\n|---|---|---|\n| 3 | 1, 3 | 2 |\n| 4 | 1, 2, 4 | 3 |\n| 22 | 1, 2, 11, 22 | 4 |\n| 23 | 1, 23 | 2 |\n\n- Un **número primo** solo se divide entre 1 y entre sí mismo: tiene **exactamente 2 divisores**. Ejemplos: 3, 11, 23.\n- Un **número compuesto** tiene **más de 2 divisores**. Ejemplos: 4, 22, 32.\n\n> **Recuerda:** el 1 no es primo ni compuesto, porque solo tiene un divisor.', 10, @tema_id);
INSERT INTO Ejercicios (Ejercicio_Contenido, Ejercicio_EsPrueba, Leccion_Id) VALUES ('# Primos y compuestos\n\n```pregunta\ntipo: opcion\nenunciado: ¿Cuál de estos números es **primo**?\nopciones:\n- [x] 37\n- [ ] 21\n- [ ] 77\n- [ ] 51\nexplicacion: 37 solo se divide entre 1 y 37. En cambio $21 = 3 \\times 7$, $77 = 7 \\times 11$ y $51 = 3 \\times 17$.\n```\n\n```pregunta\ntipo: opcion\nenunciado: ¿Cuál de estos números es **compuesto**?\nopciones:\n- [x] 91\n- [ ] 17\n- [ ] 29\n- [ ] 67\nexplicacion: $91 = 7 \\times 13$, así que tiene más de 2 divisores. Los demás son primos.\n```\n\n```pregunta\ntipo: numero\nenunciado: ¿Cuántos divisores tiene el número 12?\nrespuesta: 6\nexplicacion: Los divisores de 12 son 1, 2, 3, 4, 6 y 12: son 6.\n```\n\n```pregunta\ntipo: numero\nenunciado: ¿Cuántos divisores tiene cualquier número primo?\nrespuesta: 2\nexplicacion: Un número primo solo tiene dos divisores: el 1 y él mismo.\n```\n\n```pregunta\ntipo: opcion\nenunciado: El número 1 es…\nopciones:\n- [ ] Primo\n- [ ] Compuesto\n- [x] Ni primo ni compuesto\nmezclar: no\nexplicacion: El 1 tiene un solo divisor, por eso no es primo ni compuesto.\n```', FALSE, LAST_INSERT_ID());

-- Lección 1.2: Descomposición en factores primos
INSERT INTO Lecciones (Leccion_Nombre, Leccion_Contenido, Leccion_Orden, Tema_Id) VALUES ('Descomposición en factores primos', 'Un **factor primo** es un número primo que divide exactamente a otro número. **Descomponer en factores primos** es escribir un número como una multiplicación de números primos.\n\n**Ejemplo:** descomponer 24.\n\n| Número | Divide entre |\n|---|---|\n| 24 | 2 |\n| 12 | 2 |\n| 6 | 2 |\n| 3 | 3 |\n| 1 | |\n\nSe divide entre el menor primo posible hasta llegar a 1. Entonces:\n\n$$24 = 2 \\times 2 \\times 2 \\times 3$$\n\n**Otro ejemplo:** $45 = 3 \\times 3 \\times 5$\n\n> **Recuerda:** prueba primero con 2, luego con 3, 5, 7… y sigue hasta obtener 1.', 20, @tema_id);
INSERT INTO Ejercicios (Ejercicio_Contenido, Ejercicio_EsPrueba, Leccion_Id) VALUES ('# Descomposición en factores primos\n\n```pregunta\ntipo: opcion\nenunciado: ¿Cuál es la descomposición en factores primos de 36?\nopciones:\n- [x] $2 \\times 2 \\times 3 \\times 3$\n- [ ] $4 \\times 9$\n- [ ] $2 \\times 3 \\times 6$\n- [ ] $2 \\times 2 \\times 2 \\times 3$\nexplicacion: $36 \\div 2 = 18$, $18 \\div 2 = 9$, $9 \\div 3 = 3$, $3 \\div 3 = 1$. Entonces $36 = 2 \\times 2 \\times 3 \\times 3$. El 4, el 9 y el 6 no son primos.\n```\n\n```pregunta\ntipo: opcion\nenunciado: ¿Cuál es la descomposición en factores primos de 72?\nopciones:\n- [x] $2 \\times 2 \\times 2 \\times 3 \\times 3$\n- [ ] $8 \\times 9$\n- [ ] $2 \\times 2 \\times 2 \\times 9$\n- [ ] $2 \\times 2 \\times 3 \\times 3 \\times 3$\nexplicacion: $72 = 2 \\times 36 = 2 \\times 2 \\times 18 = 2 \\times 2 \\times 2 \\times 9 = 2 \\times 2 \\times 2 \\times 3 \\times 3$.\n```\n\n```pregunta\ntipo: numero\nvariables: p = 2|3|5, q = 3|5|7, r = 2|3|11\nenunciado: ¿Qué número tiene como descomposición en factores primos $[[p]] \\times [[q]] \\times [[r]]$?\nrespuesta: p*q*r\nexplicacion: Se multiplican los factores: $[[p]] \\times [[q]] \\times [[r]] = [[p*q*r]]$.\n```\n\n```pregunta\ntipo: numero\nenunciado: ¿Cuál es el menor factor primo de 105?\nrespuesta: 3\nexplicacion: 105 no se divide entre 2 (es impar), pero sí entre 3: $105 \\div 3 = 35$.\n```', FALSE, LAST_INSERT_ID());

-- Lección 1.3: Mínimo común múltiplo (MCM)
INSERT INTO Lecciones (Leccion_Nombre, Leccion_Contenido, Leccion_Orden, Tema_Id) VALUES ('Mínimo común múltiplo (MCM)', 'Los **múltiplos** de un número se obtienen al multiplicarlo por 1, 2, 3, 4… El **mínimo común múltiplo (MCM)** de dos números es el **menor múltiplo que tienen en común**.\n\n**Forma 1. Enumerando múltiplos** de 6 y 8:\n\n- Múltiplos de 6: 6, 12, 18, **24**, 30, 36…\n- Múltiplos de 8: 8, 16, **24**, 32, 40…\n\nEl menor común es 24, entonces MCM(6, 8) = 24.\n\n**Forma 2. Con factores primos:** se multiplican los factores **comunes y no comunes**, tomando cada uno las veces que más aparece.\n\n$$6 = 2 \\times 3 \\qquad 8 = 2 \\times 2 \\times 2$$\n$$\\text{MCM}(6, 8) = 2 \\times 2 \\times 2 \\times 3 = 24$$', 30, @tema_id);
INSERT INTO Ejercicios (Ejercicio_Contenido, Ejercicio_EsPrueba, Leccion_Id) VALUES ('# Mínimo común múltiplo\n\n```pregunta\ntipo: numero\nvariables: a = 4|6|8|10, b = 9|12|15\nenunciado: Encuentra el MCM de [[a]] y [[b]].\nrespuesta: mcm(a, b)\nexplicacion: El menor número que es múltiplo de [[a]] y de [[b]] a la vez es [[mcm(a, b)]].\n```\n\n```pregunta\ntipo: numero\nenunciado: Encuentra el MCM de 15 y 20.\nrespuesta: 60\nexplicacion: $15 = 3 \\times 5$ y $20 = 2 \\times 2 \\times 5$. MCM $= 2 \\times 2 \\times 3 \\times 5 = 60$.\n```\n\n```pregunta\ntipo: numero\nenunciado: Encuentra el MCM de 7 y 14.\nrespuesta: 14\nexplicacion: 14 ya es múltiplo de 7 ($7 \\times 2 = 14$), así que el MCM es 14.\n```\n\n```pregunta\ntipo: numero\nenunciado: Un bus sale de la terminal cada 6 minutos y otro cada 8 minutos. Si salen juntos ahora, ¿dentro de cuántos minutos volverán a salir juntos?\nrespuesta: 24\nexplicacion: Se busca el MCM de 6 y 8, que es 24 minutos.\n```', FALSE, LAST_INSERT_ID());

-- Lección 1.4: Máximo común divisor (MCD)
INSERT INTO Lecciones (Leccion_Nombre, Leccion_Contenido, Leccion_Orden, Tema_Id) VALUES ('Máximo común divisor (MCD)', 'El **máximo común divisor (MCD)** de dos números es el **mayor divisor que tienen en común**.\n\n**Forma 1. Enumerando divisores** de 8 y 12:\n\n- Divisores de 8: 1, 2, **4**, 8\n- Divisores de 12: 1, 2, 3, **4**, 6, 12\n\nEl mayor común es 4, entonces MCD(8, 12) = 4.\n\n**Forma 2. Con factores primos:** se multiplican **solo los factores comunes**.\n\n$$8 = 2 \\times 2 \\times 2 \\qquad 12 = 2 \\times 2 \\times 3$$\n$$\\text{MCD}(8, 12) = 2 \\times 2 = 4$$\n\n> **Diferencia con el MCM:** el MCM usa factores comunes y no comunes; el MCD solo los comunes.', 40, @tema_id);
INSERT INTO Ejercicios (Ejercicio_Contenido, Ejercicio_EsPrueba, Leccion_Id) VALUES ('# Máximo común divisor\n\n```pregunta\ntipo: numero\nvariables: a = 12|18|24, b = 30|36|42\nenunciado: Encuentra el MCD de [[a]] y [[b]].\nrespuesta: mcd(a, b)\nexplicacion: El mayor número que divide exactamente a [[a]] y a [[b]] es [[mcd(a, b)]].\n```\n\n```pregunta\ntipo: numero\nenunciado: Encuentra el MCD de 18 y 27.\nrespuesta: 9\nexplicacion: $18 = 2 \\times 3 \\times 3$ y $27 = 3 \\times 3 \\times 3$. Factores comunes: $3 \\times 3 = 9$.\n```\n\n```pregunta\ntipo: numero\nenunciado: Encuentra el MCD de 25 y 30.\nrespuesta: 5\nexplicacion: Divisores de 25: 1, 5, 25. Divisores de 30: 1, 2, 3, 5, 6, 10, 15, 30. El mayor común es 5.\n```\n\n```pregunta\ntipo: numero\nenunciado: Se tienen 24 manzanas y 36 naranjas. Se quieren repartir en bolsas iguales, sin que sobre fruta y con la mayor cantidad posible de bolsas. ¿Cuántas bolsas se pueden hacer?\nrespuesta: 12\nexplicacion: Se busca el MCD de 24 y 36, que es 12. Cada bolsa lleva 2 manzanas y 3 naranjas.\n```', FALSE, LAST_INSERT_ID());

-- Tema 2: Números positivos y negativos
INSERT INTO Temas (Tema_Nombre, Tema_Orden, Plan_Id) VALUES ('Números positivos y negativos', 20, @plan_id);
SET @tema_id = LAST_INSERT_ID();

-- Lección 2.1: Significado de números positivos y negativos
INSERT INTO Lecciones (Leccion_Nombre, Leccion_Contenido, Leccion_Orden, Tema_Id) VALUES ('Significado de números positivos y negativos', 'El 24 de enero de 2017 se registraron $+15$ °C en Guatemala y $-5$ °C en Quetzaltenango.\n\n- Las temperaturas **sobre** 0 °C se escriben con signo **+**: $+15$ °C se lee "más 15 grados".\n- Las temperaturas **bajo** 0 °C se escriben con signo **−**: $-5$ °C se lee "menos 5 grados".\n\nA un número con signo + se le llama **número positivo** y a uno con signo − **número negativo**. El signo + se puede omitir: $+3 = 3$.\n\n| Negativos | | Positivos |\n|---|---|---|\n| $-3, -2, -1$ | $0$ | $+1, +2, +3$ |\n\n> **Recuerda:** el cero no es positivo ni negativo.\n\nLos números con signo también sirven para direcciones: si 15 km al Este es $+15$ km, entonces 25 km al Oeste es $-25$ km.', 10, @tema_id);
INSERT INTO Ejercicios (Ejercicio_Contenido, Ejercicio_EsPrueba, Leccion_Id) VALUES ('# Positivos y negativos\n\n```pregunta\ntipo: opcion\nenunciado: ¿Cómo se escribe una temperatura de 11 °C **debajo** de 0 °C?\nopciones:\n- [x] $-11$ °C\n- [ ] $+11$ °C\n- [ ] $11$ °C\nmezclar: no\nexplicacion: Las temperaturas bajo cero llevan signo negativo: $-11$ °C.\n```\n\n```pregunta\ntipo: opcion\nenunciado: ¿Cómo se escribe una temperatura de 3 °C **arriba** de 0 °C?\nopciones:\n- [ ] $-3$ °C\n- [x] $+3$ °C\n- [ ] $0$ °C\nmezclar: no\nexplicacion: Las temperaturas sobre cero son positivas: $+3$ °C.\n```\n\n```pregunta\ntipo: opcion\nenunciado: El número 0 es…\nopciones:\n- [ ] Positivo\n- [ ] Negativo\n- [x] Ni positivo ni negativo\nmezclar: no\nexplicacion: El cero separa a los números positivos de los negativos y no pertenece a ninguno de los dos grupos.\n```\n\n```pregunta\ntipo: opcion\nenunciado: Si la posición de un carro a 15 km al Este se expresa como $+15$ km, ¿cómo se expresa la de otro carro a 25 km al **Oeste**?\nopciones:\n- [x] $-25$ km\n- [ ] $+25$ km\n- [ ] $-15$ km\n- [ ] $+10$ km\nexplicacion: El Oeste es la dirección contraria al Este, por eso lleva signo negativo: $-25$ km.\n```', FALSE, LAST_INSERT_ID());

-- Lección 2.2: Números enteros en la recta numérica
INSERT INTO Lecciones (Leccion_Nombre, Leccion_Contenido, Leccion_Orden, Tema_Id) VALUES ('Números enteros en la recta numérica', 'Los números $+1, +2, +3, \\dots$ son los **enteros positivos**, y $-1, -2, -3, \\dots$ son los **enteros negativos**. Los positivos, los negativos y el 0 forman los **números enteros**.\n\nEn la recta numérica:\n\n- Al punto 0 se le llama **origen**.\n- Los positivos están a la **derecha** del 0: $+3$ está 3 unidades a la derecha.\n- Los negativos están a la **izquierda** del 0: $-3$ está 3 unidades a la izquierda.\n\n$$\\dots,\\; -3,\\; -2,\\; -1,\\; 0,\\; +1,\\; +2,\\; +3,\\; \\dots$$\n\n> **Recuerda:** hacia la derecha es la **dirección positiva** y hacia la izquierda la **dirección negativa**.', 20, @tema_id);
INSERT INTO Ejercicios (Ejercicio_Contenido, Ejercicio_EsPrueba, Leccion_Id) VALUES ('# Enteros en la recta numérica\n\n```pregunta\ntipo: opcion\nenunciado: ¿Dónde se ubica el número $-4$ en la recta numérica?\nopciones:\n- [x] 4 unidades a la izquierda del 0\n- [ ] 4 unidades a la derecha del 0\n- [ ] En el origen\nexplicacion: Los números negativos están a la izquierda del 0.\n```\n\n```pregunta\ntipo: numero\nvariables: n = 2..9\nenunciado: ¿Qué número está [[n]] unidades a la **izquierda** del origen?\nrespuesta: -n\nexplicacion: A la izquierda del 0 están los negativos: $-[[n]]$.\n```\n\n```pregunta\ntipo: numero\nenunciado: ¿Qué número está 3 unidades a la **derecha** de $-5$?\nrespuesta: -2\nexplicacion: Desde $-5$ avanzamos a la derecha: $-4, -3, -2$. Llegamos a $-2$.\n```\n\n```pregunta\ntipo: opcion\nenunciado: ¿Cómo se llama el punto 0 de la recta numérica?\nopciones:\n- [x] Origen\n- [ ] Vértice\n- [ ] Centro positivo\nexplicacion: Al punto 0 se le llama origen.\n```', FALSE, LAST_INSERT_ID());

-- Lección 2.3: Valor absoluto
INSERT INTO Lecciones (Leccion_Nombre, Leccion_Contenido, Leccion_Orden, Tema_Id) VALUES ('Valor absoluto', 'El **valor absoluto** de un número es su **distancia al 0** en la recta numérica. Se escribe entre barras: $|\\;\\;|$.\n\n- $|+3| = 3$ porque hay 3 unidades entre 0 y $+3$.\n- $|-3| = 3$ porque hay 3 unidades entre 0 y $-3$.\n\nEl valor absoluto **nunca es negativo**, porque es una distancia.\n\nA los números que están a la misma distancia del 0, como $-2$ y $+2$, se les llama **números opuestos**.', 30, @tema_id);
INSERT INTO Ejercicios (Ejercicio_Contenido, Ejercicio_EsPrueba, Leccion_Id) VALUES ('# Valor absoluto\n\n```pregunta\ntipo: numero\nvariables: n = 2..15\nenunciado: ¿Cuál es el valor de $|-[[n]]|$?\nrespuesta: n\nexplicacion: $-[[n]]$ está a [[n]] unidades del 0, entonces $|-[[n]]| = [[n]]$.\n```\n\n```pregunta\ntipo: numero\nenunciado: ¿Cuál es el valor de $|+10|$?\nrespuesta: 10\nexplicacion: $+10$ está a 10 unidades del 0.\n```\n\n```pregunta\ntipo: numero\nenunciado: ¿Cuántas unidades hay entre 0 y $-4$?\nrespuesta: 4\nexplicacion: Es el valor absoluto de $-4$: $|-4| = 4$.\n```\n\n```pregunta\ntipo: opcion\nenunciado: ¿Cuál es el número opuesto de $-6$?\nopciones:\n- [x] $+6$\n- [ ] $-6$\n- [ ] $0$\n- [ ] $\\frac{1}{6}$\nexplicacion: $-6$ y $+6$ están a la misma distancia del 0, en lados contrarios.\n```', FALSE, LAST_INSERT_ID());

-- Lección 2.4: Comparación de números enteros
INSERT INTO Lecciones (Leccion_Nombre, Leccion_Contenido, Leccion_Orden, Tema_Id) VALUES ('Comparación de números enteros', 'En la recta numérica, **el número que está más a la derecha es el mayor**.\n\n- $+5$ está más a la derecha que $+3$, entonces $+5$ es mayor.\n- $-1$ está más a la derecha que $-5$, entonces **$-1$ es mayor que $-5$**.\n\nPara comparar se usan los **signos de desigualdad**:\n\n| Signo | Se lee | Ejemplo |\n|---|---|---|\n| $>$ | "es mayor que" | $-2 > -5$ |\n| $<$ | "es menor que" | $-5 < -2$ |\n\n> **Recuerda:** entre dos negativos, es mayor el que tiene **menor valor absoluto**. Cualquier positivo es mayor que cualquier negativo.', 40, @tema_id);
INSERT INTO Ejercicios (Ejercicio_Contenido, Ejercicio_EsPrueba, Leccion_Id) VALUES ('# Comparación de enteros\n\n```pregunta\ntipo: opcion\nenunciado: ¿Cuál es el número mayor?\nopciones:\n- [x] $-1$\n- [ ] $-5$\nmezclar: no\nexplicacion: $-1$ está más a la derecha que $-5$ en la recta numérica.\n```\n\n```pregunta\ntipo: opcion\nenunciado: ¿Cuál de estas relaciones es correcta?\nopciones:\n- [x] $-2 > -5$\n- [ ] $-2 < -5$\n- [ ] $-5 > -2$\nexplicacion: $-2$ está a la derecha de $-5$, por eso $-2$ es mayor: $-2 > -5$.\n```\n\n```pregunta\ntipo: opcion\nenunciado: Ordena de **menor a mayor**: $-3, +2, -5, +1$\nopciones:\n- [x] $-5,\\ -3,\\ +1,\\ +2$\n- [ ] $-3,\\ -5,\\ +1,\\ +2$\n- [ ] $+1,\\ +2,\\ -3,\\ -5$\n- [ ] $-5,\\ -3,\\ +2,\\ +1$\nexplicacion: De izquierda a derecha en la recta: $-5, -3, +1, +2$.\n```\n\n```pregunta\ntipo: opcion\nenunciado: ¿Cuál es el número **menor**: $0$ o $-4$?\nopciones:\n- [x] $-4$\n- [ ] $0$\nmezclar: no\nexplicacion: Todo número negativo es menor que 0.\n```', FALSE, LAST_INSERT_ID());

-- Tema 3: Suma y resta de números enteros
INSERT INTO Temas (Tema_Nombre, Tema_Orden, Plan_Id) VALUES ('Suma y resta de números enteros', 30, @plan_id);
SET @tema_id = LAST_INSERT_ID();

-- Lección 3.1: Suma de números con signos iguales
INSERT INTO Lecciones (Leccion_Nombre, Leccion_Contenido, Leccion_Orden, Tema_Id) VALUES ('Suma de números con signos iguales', 'Si un movimiento al Este es positivo y al Oeste es negativo:\n\n- Juan avanza 3 km al Este y luego 2 km más al Este: $(+3) + (+2) = +5$. Está 5 km al Este.\n- Mario avanza 1 km al Oeste y luego 2 km más al Oeste: $(-1) + (-2) = -3$. Está 3 km al Oeste.\n\n**Para sumar dos números con el mismo signo:**\n\n1. Se escribe el **signo común**.\n2. Se **suman los valores absolutos**.\n\n$$(+3) + (+5) = +(3 + 5) = +8 \\qquad (-3) + (-5) = -(3 + 5) = -8$$', 10, @tema_id);
INSERT INTO Ejercicios (Ejercicio_Contenido, Ejercicio_EsPrueba, Leccion_Id) VALUES ('# Suma con signos iguales\n\n```pregunta\ntipo: numero\nvariables: a = 2..9, b = 2..9\nenunciado: Calcula $(+[[a]]) + (+[[b]])$\nrespuesta: a + b\nexplicacion: Signo común +, y se suman: $+([[a]] + [[b]]) = +[[a+b]]$\n```\n\n```pregunta\ntipo: numero\nvariables: a = 2..9, b = 2..9\nenunciado: Calcula $(-[[a]]) + (-[[b]])$\nrespuesta: -(a + b)\nexplicacion: Signo común −, y se suman: $-([[a]] + [[b]]) = -[[a+b]]$\n```\n\n```pregunta\ntipo: numero\nenunciado: Calcula $(-8) + (-9)$\nrespuesta: -17\nexplicacion: $-(8 + 9) = -17$\n```\n\n```pregunta\ntipo: numero\nenunciado: Mario camina 1 km hacia el Oeste y luego 2 km más hacia el Oeste. Si el Este es positivo, ¿en qué posición queda? (escribe el número con su signo)\nrespuesta: -3\nexplicacion: $(-1) + (-2) = -3$: queda 3 km al Oeste.\n```', FALSE, LAST_INSERT_ID());

-- Lección 3.2: Suma de números con signos diferentes
INSERT INTO Lecciones (Leccion_Nombre, Leccion_Contenido, Leccion_Orden, Tema_Id) VALUES ('Suma de números con signos diferentes', 'Carlos viaja 8 km al Este y regresa 2 km al Oeste: $(+8) + (-2) = +6$.\nKarina viaja 3 km al Este y regresa 7 km al Oeste: $(+3) + (-7) = -4$.\n\n**Para sumar dos números con signos diferentes:**\n\n1. Se escribe el signo del número con **mayor valor absoluto**.\n2. Se **resta** el menor valor absoluto del mayor.\n\n$$(-9) + (+4) = -(9 - 4) = -5$$\n$$(-3) + (+5) = +(5 - 3) = +2$$\n\n> **Recuerda:** gana el signo del número "más grande" sin contar su signo.', 20, @tema_id);
INSERT INTO Ejercicios (Ejercicio_Contenido, Ejercicio_EsPrueba, Leccion_Id) VALUES ('# Suma con signos diferentes\n\n```pregunta\ntipo: numero\nvariables: a = 2..9, b = 10..15\nenunciado: Calcula $(+[[a]]) + (-[[b]])$\nrespuesta: a - b\nexplicacion: $|-[[b]]|$ es mayor, entonces el signo es −: $-([[b]] - [[a]]) = [[a-b]]$\n```\n\n```pregunta\ntipo: numero\nvariables: a = 2..9, b = 10..15\nenunciado: Calcula $(-[[a]]) + (+[[b]])$\nrespuesta: b - a\nexplicacion: $|+[[b]]|$ es mayor, entonces el signo es +: $+([[b]] - [[a]]) = +[[b-a]]$\n```\n\n```pregunta\ntipo: numero\nenunciado: Calcula $(+8) + (-2)$\nrespuesta: 6\nexplicacion: $+(8 - 2) = +6$\n```\n\n```pregunta\ntipo: numero\nenunciado: Karina sale de su casa, avanza 3 km al Este y luego regresa 7 km al Oeste. Si el Este es positivo, ¿en qué posición queda?\nrespuesta: -4\nexplicacion: $(+3) + (-7) = -(7 - 3) = -4$: queda 4 km al Oeste de su casa.\n```', FALSE, LAST_INSERT_ID());

-- Lección 3.3: Resta de números enteros
INSERT INTO Lecciones (Leccion_Nombre, Leccion_Contenido, Leccion_Orden, Tema_Id) VALUES ('Resta de números enteros', 'Restar un número es lo mismo que **sumar su opuesto**. Se cambia la resta por suma y se cambia el signo del número que se resta (sustraendo).\n\n$$(+3) - (+2) = (+3) + (-2) = +1$$\n$$(+2) - (+4) = (+2) + (-4) = -2$$\n\n**Pasos:**\n\n1. Cambia la resta por una suma.\n2. Cambia el signo del sustraendo.\n3. Resuelve la suma como ya aprendiste.\n\n**Ejemplo:** $(+4) - (+7) = (+4) + (-7) = -(7 - 4) = -3$', 30, @tema_id);
INSERT INTO Ejercicios (Ejercicio_Contenido, Ejercicio_EsPrueba, Leccion_Id) VALUES ('# Resta de enteros\n\n```pregunta\ntipo: numero\nvariables: a = 2..9, b = 10..15\nenunciado: Calcula $(+[[a]]) - (+[[b]])$\nrespuesta: a - b\nexplicacion: $(+[[a]]) + (-[[b]]) = -([[b]] - [[a]]) = [[a-b]]$\n```\n\n```pregunta\ntipo: numero\nenunciado: Calcula $(+10) - (+6)$\nrespuesta: 4\nexplicacion: $(+10) + (-6) = +(10 - 6) = +4$\n```\n\n```pregunta\ntipo: opcion\nenunciado: ¿A qué suma es igual $(+4) - (+7)$?\nopciones:\n- [x] $(+4) + (-7)$\n- [ ] $(+4) + (+7)$\n- [ ] $(-4) + (+7)$\n- [ ] $(-4) + (-7)$\nexplicacion: Se cambia la resta por suma y el signo del sustraendo: $(+4) + (-7)$.\n```\n\n```pregunta\ntipo: numero\nenunciado: Calcula $(+5) - (+15)$\nrespuesta: -10\nexplicacion: $(+5) + (-15) = -(15 - 5) = -10$\n```', FALSE, LAST_INSERT_ID());

-- Tema 4: Multiplicación de números enteros
INSERT INTO Temas (Tema_Nombre, Tema_Orden, Plan_Id) VALUES ('Multiplicación de números enteros', 40, @plan_id);
SET @tema_id = LAST_INSERT_ID();

-- Lección 4.1: Positivo por positivo o negativo
INSERT INTO Lecciones (Leccion_Nombre, Leccion_Contenido, Leccion_Orden, Tema_Id) VALUES ('Positivo por positivo o negativo', 'Una multiplicación es una suma abreviada:\n\n$$(+4) \\times (+2) = (+2) + (+2) + (+2) + (+2) = +8$$\n$$(+3) \\times (-2) = (-2) + (-2) + (-2) = -6$$\n\n- **Positivo × positivo = positivo**: $(+4) \\times (+2) = +(4 \\times 2) = +8$\n- **Positivo × negativo = negativo**: $(+3) \\times (-2) = -(3 \\times 2) = -6$\n\nSiempre se multiplican los valores absolutos y se coloca el signo según la regla. Si el resultado es positivo, el signo + se puede omitir: $3 \\times 5 = 15$.', 10, @tema_id);
INSERT INTO Ejercicios (Ejercicio_Contenido, Ejercicio_EsPrueba, Leccion_Id) VALUES ('# Multiplicación (1)\n\n```pregunta\ntipo: numero\nvariables: a = 2..9, b = 2..9\nenunciado: Calcula $(+[[a]]) \\times (+[[b]])$\nrespuesta: a*b\nexplicacion: Positivo × positivo = positivo: $+([[a]] \\times [[b]]) = [[a*b]]$\n```\n\n```pregunta\ntipo: numero\nvariables: a = 2..9, b = 2..9\nenunciado: Calcula $(+[[a]]) \\times (-[[b]])$\nrespuesta: -a*b\nexplicacion: Positivo × negativo = negativo: $-([[a]] \\times [[b]]) = [[-a*b]]$\n```\n\n```pregunta\ntipo: numero\nenunciado: Calcula $6 \\times (-8)$\nrespuesta: -48\nexplicacion: $-(6 \\times 8) = -48$\n```\n\n```pregunta\ntipo: opcion\nenunciado: Al multiplicar un número positivo por un número negativo, el resultado es…\nopciones:\n- [ ] Positivo\n- [x] Negativo\n- [ ] Siempre cero\nmezclar: no\nexplicacion: $(+) \\times (-) = (-)$\n```', FALSE, LAST_INSERT_ID());

-- Lección 4.2: Negativo por positivo
INSERT INTO Lecciones (Leccion_Nombre, Leccion_Contenido, Leccion_Orden, Tema_Id) VALUES ('Negativo por positivo', 'Observa cómo el resultado baja de 2 en 2:\n\n| Operación | Resultado |\n|---|---|\n| $(+2) \\times (+2)$ | $+4$ |\n| $(+1) \\times (+2)$ | $+2$ |\n| $0 \\times (+2)$ | $0$ |\n| $(-1) \\times (+2)$ | $-2$ |\n| $(-2) \\times (+2)$ | $-4$ |\n\nAl multiplicar un **número negativo por un número positivo**, el resultado es **negativo**. Se coloca el signo − y se multiplican los valores absolutos.\n\n$$(-5) \\times 6 = -(5 \\times 6) = -30$$', 20, @tema_id);
INSERT INTO Ejercicios (Ejercicio_Contenido, Ejercicio_EsPrueba, Leccion_Id) VALUES ('# Multiplicación (2)\n\n```pregunta\ntipo: numero\nvariables: a = 2..9, b = 2..9\nenunciado: Calcula $(-[[a]]) \\times (+[[b]])$\nrespuesta: -a*b\nexplicacion: Negativo × positivo = negativo: $-([[a]] \\times [[b]]) = [[-a*b]]$\n```\n\n```pregunta\ntipo: numero\nenunciado: Calcula $(-9) \\times 9$\nrespuesta: -81\nexplicacion: $-(9 \\times 9) = -81$\n```\n\n```pregunta\ntipo: numero\nenunciado: Calcula $(-4) \\times 7$\nrespuesta: -28\nexplicacion: $-(4 \\times 7) = -28$\n```\n\n```pregunta\ntipo: opcion\nenunciado: ¿Qué signo tiene el resultado de $(-) \\times (+)$?\nopciones:\n- [ ] Positivo\n- [x] Negativo\nmezclar: no\nexplicacion: Negativo por positivo da negativo.\n```', FALSE, LAST_INSERT_ID());

-- Lección 4.3: Multiplicación de dos números negativos
INSERT INTO Lecciones (Leccion_Nombre, Leccion_Contenido, Leccion_Orden, Tema_Id) VALUES ('Multiplicación de dos números negativos', 'Ahora el resultado sube de 2 en 2:\n\n| Operación | Resultado |\n|---|---|\n| $(+1) \\times (-2)$ | $-2$ |\n| $0 \\times (-2)$ | $0$ |\n| $(-1) \\times (-2)$ | $+2$ |\n| $(-2) \\times (-2)$ | $+4$ |\n| $(-3) \\times (-2)$ | $+6$ |\n\nAl multiplicar **dos números negativos**, el resultado es **positivo**.\n\n$$(-8) \\times (-5) = +(8 \\times 5) = 40$$\n\n**Resumen de la regla de los signos:**\n\n| | $+$ | $-$ |\n|---|---|---|\n| $+$ | $+$ | $-$ |\n| $-$ | $-$ | $+$ |', 30, @tema_id);
INSERT INTO Ejercicios (Ejercicio_Contenido, Ejercicio_EsPrueba, Leccion_Id) VALUES ('# Multiplicación (3)\n\n```pregunta\ntipo: numero\nvariables: a = 2..9, b = 2..9\nenunciado: Calcula $(-[[a]]) \\times (-[[b]])$\nrespuesta: a*b\nexplicacion: Negativo × negativo = positivo: $+([[a]] \\times [[b]]) = [[a*b]]$\n```\n\n```pregunta\ntipo: numero\nenunciado: Calcula $(-9) \\times (-7)$\nrespuesta: 63\nexplicacion: $+(9 \\times 7) = 63$\n```\n\n```pregunta\ntipo: numero\nenunciado: Calcula $(-6) \\times (-8)$\nrespuesta: 48\nexplicacion: $+(6 \\times 8) = 48$\n```\n\n```pregunta\ntipo: opcion\nenunciado: ¿Cuál de estas multiplicaciones da un resultado **negativo**?\nopciones:\n- [x] $(-3) \\times (+4)$\n- [ ] $(-3) \\times (-4)$\n- [ ] $(+3) \\times (+4)$\nexplicacion: Solo cuando los signos son diferentes el resultado es negativo: $(-3) \\times (+4) = -12$.\n```', FALSE, LAST_INSERT_ID());

COMMIT;

SELECT p.Plan_Id, p.Plan_Nombre, COUNT(DISTINCT t.Tema_Id) AS Temas, COUNT(DISTINCT l.Leccion_Id) AS Lecciones, COUNT(e.Ejercicio_Id) AS Ejercicios
FROM Planes_Estudio p JOIN Temas t ON t.Plan_Id = p.Plan_Id JOIN Lecciones l ON l.Tema_Id = t.Tema_Id
LEFT JOIN Ejercicios e ON e.Leccion_Id = l.Leccion_Id WHERE p.Plan_Id = @plan_id GROUP BY p.Plan_Id, p.Plan_Nombre;
